/**
 * PROTOTYPE demo: one schema-first service, three peers.
 *
 *   pnpm --filter @effect/protobuf demo
 *
 * 1. prints the `.proto` rendered from the Effect schemas
 * 2. serves the service over Connect with `ConnectServer`
 * 3. calls it from the Effect client (binary) and from a stock
 *    `@connectrpc/connect-node` client generated by protoc-gen-es (JSON)
 */
import { createClient } from "@connectrpc/connect"
import { createConnectTransport } from "@connectrpc/connect-node"
import * as NodeHttpServer from "@effect/platform-node/NodeHttpServer"
import * as NodeRuntime from "@effect/platform-node/NodeRuntime"
import { Console, DateTime, Effect, Layer, Schema, Stream } from "effect"
import { FetchHttpClient, HttpRouter, HttpServer } from "effect/http"
import type * as NetAddress from "effect/net/NetAddress"
import * as Http from "node:http"
import { ConnectClient, ConnectServer, Protobuf, ProtoFile } from "../src/index.ts"
// oxlint-disable-next-line effect/no-js-extension-imports -- generated JS fixture
import { PointService as PointServiceEs } from "../test/fixtures/gen-es/acme/v1/kitchen_sink_pb.js"
import { PointNotFound, PointService, Shapes } from "../test/fixtures/schemas.ts"

const Handlers = PointService.toLayer({
  GetPoint: ({ id }) => id === 404 ? Effect.fail(new PointNotFound({ id })) : Effect.succeed({ x: id, y: id * 2 }),
  ListPoints: ({ limit }) => Stream.range(1, limit).pipe(Stream.map((i) => ({ x: i, y: -i }))),
  Ping: () => Effect.succeed({})
})

const program = Effect.gen(function*() {
  yield* Console.log("--- .proto rendered from the schemas ---")
  yield* Console.log(ProtoFile.make({ package: "acme.v1", services: [PointService] }))

  yield* Console.log("--- codec ---")
  const shapes = {
    numbers: [1, 2, 3],
    names: [],
    points: [],
    colors: [],
    counts: { a: 1 },
    labels: {},
    namedPoints: {},
    primary: 1 as const,
    shape: { _tag: "label" as const, value: "hello" }
  }
  const bytes = Schema.encodeSync(Protobuf.toCodec(Shapes))(shapes)
  yield* Console.log("Shapes binary:", Buffer.from(bytes).toString("hex"))
  yield* Console.log("Shapes JSON:  ", JSON.stringify(Schema.encodeSync(Protobuf.toCodecJson(Shapes))(shapes)))

  const server = yield* HttpServer.HttpServer
  const baseUrl = `http://127.0.0.1:${(server.address as NetAddress.InetAddress).port}`
  yield* Console.log(`\n--- serving acme.v1.PointService on ${baseUrl} ---`)

  const client = yield* ConnectClient.make(PointService, { baseUrl })
  yield* Console.log("[effect client] GetPoint(3) =", yield* client.GetPoint({ id: 3 }))
  yield* Console.log("[effect client] ListPoints(3) =", yield* Stream.runCollect(client.ListPoints({ limit: 3 })))
  yield* Console.log("[effect client] GetPoint(404) =", yield* Effect.flip(client.GetPoint({ id: 404 })))

  const es = createClient(
    PointServiceEs,
    createConnectTransport({ baseUrl, httpVersion: "1.1", useBinaryFormat: false })
  )
  const point = yield* Effect.promise(() => es.getPoint({ id: 7 }))
  yield* Console.log("[connect-es client] getPoint(7) =", { x: point.x, y: point.y })
  const error = yield* Effect.promise(() => es.getPoint({ id: 404 }).then(() => undefined, (e) => e))
  yield* Console.log("[connect-es client] getPoint(404) =", error.code, error.rawMessage, error.details)
  yield* Console.log("\ndone at", DateTime.formatIso(yield* DateTime.now))
})

const Server = ConnectServer.layer(PointService).pipe(
  Layer.provide(Handlers),
  HttpRouter.serve,
  Layer.provideMerge(NodeHttpServer.layer(Http.createServer, { port: 0 }))
)

program.pipe(
  Effect.scoped,
  Effect.provide([Server, FetchHttpClient.layer]),
  NodeRuntime.runMain
)
